function ScenarioModeling() {
  const [scenarios, setScenarios] = React.useState([
    { id: 1, name: 'Base Case', assumptions: 'Normal sales growth' },
    { id: 2, name: 'Best Case', assumptions: 'High sales growth' },
  ]);

  const addScenario = () => {
    const newScenario = { id: scenarios.length + 1, name: 'New Scenario', assumptions: '' };
    setScenarios([...scenarios, newScenario]);
  };

  return (
    <div className="max-w-4xl mx-auto p-4 bg-gray-100 rounded shadow">
      <h1 className="text-2xl font-semibold mb-4 text-gray-800">Scenario Modeling</h1>
      <div>
        <h2 className="text-lg font-semibold mb-2 text-gray-700">Scenarios</h2>
        {scenarios.map((scenario) => (
          <div key={scenario.id} className="bg-gray-200 p-2 rounded mb-2">
            <h3 className="font-semibold text-gray-700">{scenario.name}</h3>
            <p className="text-gray-600">{scenario.assumptions}</p>
          </div>
        ))}
        <button className="bg-gray-300 hover:bg-gray-400 text-gray-700 font-bold py-2 px-4 rounded" onClick={addScenario}>Add Scenario</button>
      </div>
      <button className="mt-4 bg-gray-400 hover:bg-gray-500 text-white font-bold py-2 px-4 rounded" onClick={() => { alert('Comparing Scenarios'); }}>Compare Scenarios</button>
      <button className="mt-4 bg-gray-400 hover:bg-gray-500 text-white font-bold py-2 px-4 rounded" onClick={() => { alert('Navigating back to Cash Flow Forecasting'); }}>Back to Cash Flow Forecasting</button>
    </div>
  );
}

function UserRegistration() {
  const [formData, setFormData] = React.useState({
    email: '',
    password: '',
    confirmPassword: '',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    alert('Submitting registration form');
  };

  return (
    <div className="max-w-md mx-auto p-4 bg-gray-100 rounded shadow">
      <h1 className="text-2xl font-semibold mb-4 text-gray-800">User Registration</h1>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label htmlFor="email" className="block text-gray-700 text-sm font-bold mb-2">Email</label>
          <input
            type="email"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          />
        </div>
        <div>
          <label htmlFor="password" className="block text-gray-700 text-sm font-bold mb-2">Password</label>
          <input
            type="password"
            id="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          />
        </div>
        <div>
          <label htmlFor="confirmPassword" className="block text-gray-700 text-sm font-bold mb-2">Confirm Password</label>
          <input
            type="password"
            id="confirmPassword"
            name="confirmPassword"
            value={formData.confirmPassword}
            onChange={handleChange}
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          />
        </div>
        <button className="bg-gray-400 hover:bg-gray-500 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline" type="submit">
          Register
        </button>
      </form>
    </div>
  );
}

function RoleManagement() {
  const [users, setUsers] = React.useState([
    { id: 1, name: 'John Doe', email: 'john.doe@example.com', role: 'admin' },
    { id: 2, name: 'Jane Smith', email: 'jane.smith@example.com', role: 'user' },
  ]);

  const handleRoleChange = (userId, newRole) => {
    const updatedUsers = users.map((user) =>
      user.id === userId ? { ...user, role: newRole } : user
    );
    setUsers(updatedUsers);
  };

  return (
    <div className="max-w-4xl mx-auto p-4 bg-gray-100 rounded shadow">
      <h1 className="text-2xl font-semibold mb-4 text-gray-800">Role Management</h1>
      <div>
        <h2 className="text-lg font-semibold mb-2 text-gray-700">Users</h2>
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Name</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Email</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Role</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {users.map((user) => (
              <tr key={user.id}>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{user.name}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{user.email}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                  <select
                    value={user.role}
                    onChange={(e) => handleRoleChange(user.id, e.target.value)}
                    className="bg-gray-100 border border-gray-300 rounded px-2 py-1"
                  >
                    <option value="admin">Admin</option>
                    <option value="user">User</option>
                  </select>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <button className="mt-4 bg-gray-400 hover:bg-gray-500 text-white font-bold py-2 px-4 rounded">Save</button>
    </div>
  );
}

function AlertConfiguration() {
  const [threshold, setThreshold] = React.useState(0);
  const [notificationSettings, setNotificationSettings] = React.useState({
    email: true,
    sms: false,
  });

  const handleThresholdChange = (e) => {
    setThreshold(parseFloat(e.target.value));
  };

  const handleNotificationChange = (e) => {
    setNotificationSettings({ ...notificationSettings, [e.target.name]: e.target.checked });
  };

  return (
    <div className="max-w-md mx-auto p-4 bg-gray-100 rounded shadow">
      <h1 className="text-2xl font-semibold mb-4 text-gray-800">Alert Configuration</h1>
      <div>
        <label htmlFor="threshold" className="block text-gray-700 text-sm font-bold mb-2">Low Cash Threshold</label>
        <input
          type="number"
          id="threshold"
          name="threshold"
          value={threshold}
          onChange={handleThresholdChange}
          className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
        />
      </div>
      <div className="mt-4">
        <h2 className="text-lg font-semibold mb-2 text-gray-700">Notification Settings</h2>
        <label className="inline-flex items-center">
          <input
            type="checkbox"
            name="email"
            checked={notificationSettings.email}
            onChange={handleNotificationChange}
            className="form-checkbox h-5 w-5 text-gray-600"
          />
          <span className="ml-2 text-gray-700">Email</span>
        </label>
        <label className="inline-flex items-center ml-4">
          <input
            type="checkbox"
            name="sms"
            checked={notificationSettings.sms}
            onChange={handleNotificationChange}
            className="form-checkbox h-5 w-5 text-gray-600"
          />
          <span className="ml-2 text-gray-700">SMS</span>
        </label>
      </div>
      <button className="mt-4 bg-gray-400 hover:bg-gray-500 text-white font-bold py-2 px-4 rounded">Save</button>
    </div>
  );
}

function TransactionCategorization() {
  const [transactions, setTransactions] = React.useState([
    {
      id: 1,
      date: '2024-01-15',
      description: 'Invoice Payment',
      amount: 1500,
      category: 'Uncategorized',
    },
    {
      id: 2,
      date: '2024-01-10',
      description: 'Rent',
      amount: 3000,
      category: 'Uncategorized',
    },
  ]);

  const handleCategoryChange = (transactionId, newCategory) => {
    const updatedTransactions = transactions.map((transaction) =>
      transaction.id === transactionId ? { ...transaction, category: newCategory } : transaction
    );
    setTransactions(updatedTransactions);
  };

  return (
    <div className="max-w-4xl mx-auto p-4 bg-gray-100 rounded shadow">
      <h1 className="text-2xl font-semibold mb-4 text-gray-800">Transaction Categorization</h1>
